import { pgTable, serial, integer, timestamp, varchar, decimal, index } from 'drizzle-orm/pg-core';

export const analyticsEvents = pgTable(
  'analytics_events',
  {
    id: serial('id').primaryKey(),
    eventName: varchar('event_name', { length: 100 }).notNull(),
    eventCategory: varchar('event_category', { length: 50 }).notNull(),
    userId: varchar('user_id', { length: 100 }),
    sessionId: varchar('session_id', { length: 100 }).notNull(),
    value: decimal('value', { precision: 10, scale: 2 }),
    metadata: varchar('metadata', { length: 1000 }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => ({
    eventNameIdx: index('analytics_events_event_name_idx').on(table.eventName),
    eventCategoryIdx: index('analytics_events_event_category_idx').on(table.eventCategory),
    userIdIdx: index('analytics_events_user_id_idx').on(table.userId),
    sessionIdIdx: index('analytics_events_session_id_idx').on(table.sessionId),
    createdAtIdx: index('analytics_events_created_at_idx').on(table.createdAt),
  })
);

export const dailyMetrics = pgTable(
  'daily_metrics',
  {
    id: serial('id').primaryKey(),
    date: timestamp('date', { withTimezone: true }).notNull(),
    totalEvents: integer('total_events').default(0).notNull(),
    uniqueUsers: integer('unique_users').default(0).notNull(),
    uniqueSessions: integer('unique_sessions').default(0).notNull(),
    totalRevenue: decimal('total_revenue', { precision: 12, scale: 2 }).default('0').notNull(),
    avgSessionDuration: integer('avg_session_duration').default(0).notNull(),
    bounceRate: decimal('bounce_rate', { precision: 5, scale: 2 }).default('0').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => ({
    dateIdx: index('daily_metrics_date_idx').on(table.date),
  })
);

export type AnalyticsEvent = typeof analyticsEvents.$inferSelect;
export type NewAnalyticsEvent = typeof analyticsEvents.$inferInsert;
export type DailyMetric = typeof dailyMetrics.$inferSelect;
export type NewDailyMetric = typeof dailyMetrics.$inferInsert;

