import { db } from '@/db/client';
import { analyticsEvents, dailyMetrics } from '@/db/schema';
import { sql, eq, gte, lte, count, sum, avg, distinct, desc, and } from 'drizzle-orm';
import { subDays, startOfDay, endOfDay, format } from 'date-fns';

export interface TimeRange {
  start: Date;
  end: Date;
}

export interface EventSummary {
  eventName: string;
  eventCategory: string;
  count: number;
  uniqueUsers: number;
  totalValue: number;
}

export interface DailyMetricData {
  date: string;
  totalEvents: number;
  uniqueUsers: number;
  uniqueSessions: number;
  totalRevenue: number;
  avgSessionDuration: number;
  bounceRate: number;
}

export interface DashboardData {
  eventSummaries: EventSummary[];
  dailyMetrics: DailyMetricData[];
  totals: {
    totalEvents: number;
    totalUsers: number;
    totalSessions: number;
    totalRevenue: number;
  };
}

export async function getTimeRange(days: number = 30): Promise<TimeRange> {
  const end = new Date();
  const start = subDays(end, days);
  return { start: startOfDay(start), end: endOfDay(end) };
}

export async function fetchEventSummaries(timeRange: TimeRange): Promise<EventSummary[]> {
  const results = await db
    .select({
      eventName: analyticsEvents.eventName,
      eventCategory: analyticsEvents.eventCategory,
      count: count(analyticsEvents.id),
      uniqueUsers: count(distinct(analyticsEvents.userId)),
      totalValue: sum(analyticsEvents.value),
    })
    .from(analyticsEvents)
    .where(
      and(
        gte(analyticsEvents.createdAt, timeRange.start),
        lte(analyticsEvents.createdAt, timeRange.end)
      )
    )
    .groupBy(analyticsEvents.eventName, analyticsEvents.eventCategory)
    .orderBy(desc(count(analyticsEvents.id)))
    .limit(20);

  return results.map((r) => ({
    eventName: r.eventName,
    eventCategory: r.eventCategory,
    count: r.count,
    uniqueUsers: r.uniqueUsers,
    totalValue: Number(r.totalValue ?? 0),
  }));
}

export async function fetchDailyMetrics(timeRange: TimeRange): Promise<DailyMetricData[]> {
  const results = await db
    .select()
    .from(dailyMetrics)
    .where(
      and(
        gte(dailyMetrics.date, timeRange.start),
        lte(dailyMetrics.date, timeRange.end)
      )
    )
    .orderBy(dailyMetrics.date);

  return results.map((r) => ({
    date: format(r.date, 'yyyy-MM-dd'),
    totalEvents: r.totalEvents,
    uniqueUsers: r.uniqueUsers,
    uniqueSessions: r.uniqueSessions,
    totalRevenue: Number(r.totalRevenue),
    avgSessionDuration: r.avgSessionDuration,
    bounceRate: Number(r.bounceRate),
  }));
}

export async function fetchTotals(timeRange: TimeRange) {
  const [eventsAgg, usersAgg, sessionsAgg, revenueAgg] = await Promise.all([
    db
      .select({ count: count() })
      .from(analyticsEvents)
      .where(
        and(
          gte(analyticsEvents.createdAt, timeRange.start),
          lte(analyticsEvents.createdAt, timeRange.end)
        )
      ),
    db
      .select({ count: count(distinct(analyticsEvents.userId)) })
      .from(analyticsEvents)
      .where(
        and(
          gte(analyticsEvents.createdAt, timeRange.start),
          lte(analyticsEvents.createdAt, timeRange.end)
        )
      ),
    db
      .select({ count: count(distinct(analyticsEvents.sessionId)) })
      .from(analyticsEvents)
      .where(
        and(
          gte(analyticsEvents.createdAt, timeRange.start),
          lte(analyticsEvents.createdAt, timeRange.end)
        )
      ),
    db
      .select({ sum: sum(analyticsEvents.value) })
      .from(analyticsEvents)
      .where(
        and(
          gte(analyticsEvents.createdAt, timeRange.start),
          lte(analyticsEvents.createdAt, timeRange.end)
        )
      ),
  ]);

  return {
    totalEvents: eventsAgg[0]?.count ?? 0,
    totalUsers: usersAgg[0]?.count ?? 0,
    totalSessions: sessionsAgg[0]?.count ?? 0,
    totalRevenue: Number(revenueAgg[0]?.sum ?? 0),
  };
}

export async function fetchDashboardData(days: number = 30): Promise<DashboardData> {
  const timeRange = await getTimeRange(days);
  const [eventSummaries, dailyMetrics, totals] = await Promise.all([
    fetchEventSummaries(timeRange),
    fetchDailyMetrics(timeRange),
    fetchTotals(timeRange),
  ]);

  return { eventSummaries, dailyMetrics, totals };
}

