function DailyMetricsChart({ metrics }: { metrics: DailyMetricData[] }) {
  const labels = metrics.map((m) => format(new Date(m.date), 'MMM dd'));
  const eventsData = metrics.map((m) => m.totalEvents);
  const usersData = metrics.map((m) => m.uniqueUsers);
  const revenueData = metrics.map((m) => m.totalRevenue);

  const lineData = {
    labels,
    datasets: [
      {
        label: 'Total Events',
        data: eventsData,
        borderColor: COLORS.primary,
        backgroundColor: `${COLORS.primary}20`,
        fill: true,
        tension: 0.3,
        yAxisID: 'y',
      },
      {
        label: 'Unique Users',
        data: usersData,
        borderColor: COLORS.success,
        backgroundColor: `${COLORS.success}20`,
        fill: true,
        tension: 0.3,
        yAxisID: 'y',
      },
    ],
  };

  const barData = {
    labels,
    datasets: [
      {
        label: 'Revenue ($)',
        data: revenueData,
        backgroundColor: `${COLORS.warning}80`,
        borderColor: COLORS.warning,
        borderWidth: 1,
        borderRadius: 4,
        yAxisID: 'y1',
      },
