function CategoryDistribution({ events }: { events: EventSummary[] }) {
  const categoryMap = new Map<string, number>();
  events.forEach((e) => {
    categoryMap.set(e.eventCategory, (categoryMap.get(e.eventCategory) || 0) + e.count);
  });

  const labels = Array.from(categoryMap.keys());
  const data = Array.from(categoryMap.values());
  const backgroundColors = [
    COLORS.primary,
    COLORS.secondary,
    COLORS.success,
    COLORS.warning,
    COLORS.danger,
    COLORS.muted,
  ];

  const doughnutData = {
    labels,
    datasets: [
      {
        data,
        backgroundColor: backgroundColors.slice(0, labels.length),
        borderWidth: 2,
        borderColor: '#ffffff',
      },
    ],
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 p-6">
      <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">Events by Category</h3>
